{
  "name": "@pistonex/opencode-peek",
  "version": "1.0.0",
  "description": "OpenCode TUI plugin — vista rápida (/peek, /vista) de los archivos mencionados en las respuestas del asistente",
  "type": "module",
  "license": "MIT",
  "author": "Tony Pistone <admin@pistone.com.ar>",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "peek",
    "preview",
    "tui"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/pistonex/opencode-peek.git"
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "src",
    "tui.ts",
    "README.md",
    "LICENSE"
  ],
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/peek.tsx"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.30"
  },
  "devDependencies": {
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "@types/bun": "^1.4.3",
    "@types/node": "^22.0.0",
    "solid-js": "^1.9.0",
    "typescript": "^5.5.0"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "engines": {
    "opencode": ">=2.0.0"
  }
}
